CREATE SEQUENCE public.aj_item_code;
CREATE TABLE public.items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), code text NOT NULL UNIQUE DEFAULT ('AJ-' || lpad(nextval('public.aj_item_code')::text,4,'0')), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), category text NOT NULL CHECK(category IN ('Necklaces','Chain','Ring','Earrings Jumka','Earrings Hangi','Bangles','Earrings Studs','Bracelets','Other')), purchased integer NOT NULL CHECK(purchased>=0), sold integer NOT NULL DEFAULT 0 CHECK(sold>=0 AND sold<=purchased), purchase_price numeric(12,2) NOT NULL CHECK(purchase_price>=0), selling_price numeric(12,2) NOT NULL CHECK(selling_price>=0), photo text, notes text NOT NULL DEFAULT '' CHECK(length(notes)<=1000), deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.items TO authenticated; GRANT ALL ON public.items TO service_role; GRANT USAGE ON SEQUENCE public.aj_item_code TO authenticated,service_role;
ALTER TABLE public.items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_items ON public.items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), item_id uuid NOT NULL REFERENCES public.items(id) ON DELETE RESTRICT, item_name text NOT NULL DEFAULT '', item_code text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0), cost_price numeric(12,2) NOT NULL DEFAULT 0, payment text NOT NULL CHECK(payment IN ('Cash','GPay')), date date NOT NULL, note text NOT NULL DEFAULT '' CHECK(length(note)<=1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.sales TO authenticated; GRANT ALL ON public.sales TO service_role;
ALTER TABLE public.sales ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_sales ON public.sales FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY insert_own_sales ON public.sales FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.protect_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.sold<>0 THEN RAISE EXCEPTION 'New items cannot have sold units'; END IF; IF TG_OP='UPDATE' THEN IF NEW.user_id<>OLD.user_id OR NEW.code<>OLD.code THEN RAISE EXCEPTION 'Item owner and code cannot change'; END IF; IF NEW.sold<>OLD.sold AND pg_trigger_depth()=1 THEN RAISE EXCEPTION 'Sold quantity is managed by sales'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_item BEFORE INSERT OR UPDATE ON public.items FOR EACH ROW EXECUTE FUNCTION public.protect_item();
CREATE FUNCTION public.record_stock_sale() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE product public.items; BEGIN SELECT * INTO product FROM public.items WHERE id=NEW.item_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR product.deleted THEN RAISE EXCEPTION 'Item is unavailable'; END IF; IF NEW.quantity>product.purchased-product.sold THEN RAISE EXCEPTION 'Not enough stock available'; END IF; IF NEW.date> (now() AT TIME ZONE 'Asia/Kolkata')::date THEN RAISE EXCEPTION 'Sale date cannot be in the future'; END IF; NEW.item_name:=product.name; NEW.item_code:=product.code; NEW.category:=product.category; NEW.cost_price:=product.purchase_price; UPDATE public.items SET sold=sold+NEW.quantity WHERE id=product.id; RETURN NEW; END $$;
CREATE TRIGGER sale_stock BEFORE INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.record_stock_sale();
CREATE INDEX items_owner ON public.items(user_id); CREATE INDEX sales_owner_date ON public.sales(user_id,date DESC);